examples.template:
NavigationStack {
    Group {
        if query.isEmpty {
            List {
                Text({{description}})
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                    .listRowBackground(Color.clear)
                ForEach(categories, id: \.self) { category in
                    Section(category) {
                        ForEach(articles.filter { $0.category == category }, id: \.id) { article in
                            NavigationLink(value: article.id) {
                                Label {
                                    Text(article.title)
                                } icon: {
                                    Image(systemName: "doc.text").foregroundStyle(theme.colors.textMuted)
                                }
                                .monarchTextStyle(.body)
                            }
                        }
                    }
                }
                Section {
                    if let url = URL(string: "https://example.com/support") {
                        Link({{contact}}, destination: url)
                            .buttonStyle(.monarch(.secondary))
                    }
                }
            }
        } else {
            MonarchSearchResults(
                groups: [MonarchSearchResultGroup(nil, id: "articles", results: matches)],
                query: query,
                onSelect: { _, _ in }
            )
        }
    }
    .monarchCanvas()
    .monarchSearchable(text: $query, prompt: {{search}})
    .navigationTitle({{title}})
    #if os(iOS)
    .navigationBarTitleDisplayMode(.large)
    #endif
    .navigationDestination(for: String.self) { id in
        Text(articles.first { $0.id == id }?.title ?? "")
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var query = ""
private let articles: [(id: String, title: String, category: String)] = [
    ({{articles.0.id}}, {{articles.0.title}}, {{articles.0.category}}),
    ({{articles.1.id}}, {{articles.1.title}}, {{articles.1.category}}),
    ({{articles.2.id}}, {{articles.2.title}}, {{articles.2.category}}),
    ({{articles.3.id}}, {{articles.3.title}}, {{articles.3.category}}),
    ({{articles.4.id}}, {{articles.4.title}}, {{articles.4.category}}),
    ({{articles.5.id}}, {{articles.5.title}}, {{articles.5.category}}),
]
private var matches: [MonarchSearchResult] {
    articles
        .filter { article in
            query.split(separator: " ").allSatisfy { "\(article.title) \(article.category)".localizedStandardContains($0) }
        }
        .map { MonarchSearchResult($0.title, id: $0.id, path: [$0.category]) }
}
private var categories: [String] {
    articles.map(\.category).reduce(into: [String]()) { if !$0.contains($1) { $0.append($1) } }
}

